import json
from collections import Counter

task_id = "task-5c839a47"
workspace = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u057/system/state/workspace"
data_path = workspace + "/programs/" + task_id + ".json"

with open(data_path, 'r') as f:
    demos = json.load(f)

def fill_between_dots(grid):
    H, W = len(grid), len(grid[0])
    counts = Counter(c for row in grid for c in row)
    dot = counts.most_common()[-1][0]  # minority color
    bg = counts.most_common()[0][0]  # major color

    result = [row[:] for row in grid]

    # Fill horizontally between dots
    for r in range(H):
        dots_in_row = [c for c in range(W) if grid[r][c] == dot]
        for i in range(len(dots_in_row)):
            for j in range(i+1, len(dots_in_row)):
                c1, c2 = dots_in_row[i], dots_in_row[j]
                for c in range(c1 + 1, c2):
                    if result[r][c] == bg:
                        result[r][c] = 3

    # Fill vertically between dots
    for c in range(W):
        dots_in_col = [r for r in range(H) if grid[r][c] == dot]
        for i in range(len(dots_in_col)):
            for j in range(i+1, len(dots_in_col)):
                r1, r2 = dots_in_col[i], dots_in_col[j]
                for r in range(r1 + 1, r2):
                    if result[r][c] == bg:
                        result[r][c] = 3

    return result

# Full test on all demos
